#!/usr/bin/env python3
# -*- coding: utf-8 -*-

slides_part3 = [{'id': 17, 'title': 'Mass Laws, Dalton', 'subtitle': 'Quiz Challenge 1 (10 Questions): Activities 9.1–9.3, Lavoisier, Proust & Dalton', 'speech': '', 'questions': [{'question': 'Q1. In Activity 9.1, dissolving table salt completely in water demonstrates that during a physical change:', 'options': ['Total mass decreases', 'Total mass remains unchanged', 'Total mass doubles', 'Salt atoms vanish'], 'answer': 1, 'hint': 'Weighing before and after dissolving shows identical scale readings.', 'explanation': 'Total mass remains unchanged during physical dissolution.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Weighing before and after dissolving shows identical scale readings.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: Total mass remains unchanged during physical dissolution.']}, {'question': 'Q2. In Activity 9.2 (baking soda + vinegar), why is a balloon attached to the flask in Set-up 2?', 'options': ['To speed up cooling', 'To trap the generated CO₂ gas in a closed system so total mass stays conserved', 'To add oxygen', 'To colour the solution'], 'answer': 1, 'hint': 'Gas escaping in an open flask makes the scale reading drop.', 'explanation': 'The balloon seals the flask, capturing CO₂ gas and verifying conservation of mass.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Gas escaping in an open flask makes the scale reading drop.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: The balloon seals the flask, capturing CO₂ gas and verifying conservation of mass.']}, {'question': 'Q3. In Activity 9.3, mixing clear Na₂SO₄ and BaCl₂ solutions produces a white precipitate of:', 'options': ['Sodium chloride (NaCl)', 'Barium sulfate (BaSO₄)', 'Calcium carbonate (CaCO₃)', 'Barium oxide (BaO)'], 'answer': 1, 'hint': 'Double displacement swaps ions to form insoluble BaSO₄.', 'explanation': 'Na₂SO₄ + BaCl₂ → BaSO₄↓ (white precipitate) + 2 NaCl.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Double displacement swaps ions to form insoluble BaSO₄.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: Na₂SO₄ + BaCl₂ → BaSO₄↓ (white precipitate) + 2 NaCl.']}, {'question': 'Q4. In Example 9.1, 6.92 g of CaCO₃ + HCl reactants produce CaCl₂ + H₂O + CO₂. What is the total mass of products?', 'options': ['3.46 g', '6.92 g', '13.84 g', '5.00 g'], 'answer': 1, 'hint': "Apply Lavoisier's Law of Conservation of Mass.", 'explanation': 'Mass of products equals mass of reactants = 6.92 g.', 'solution_steps': ["Step 1: Identify the relevant principle or formula: Apply Lavoisier's Law of Conservation of Mass.", 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: Mass of products equals mass of reactants = 6.92 g.']}, {'question': 'Q5. In Example 9.2, 3 g of carbon burns in 8 g of oxygen to form 11 g of CO₂. What mass of CO₂ forms from 2.4 g of carbon?', 'options': ['6.4 g', '8.8 g', '11.0 g', '4.4 g'], 'answer': 1, 'hint': 'Scale proportionally: (11 / 3) × 2.4.', 'explanation': '2.4 g is 0.8 times 3 g, so CO₂ = 0.8 × 11 g = 8.8 g.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Scale proportionally: (11 / 3) × 2.4.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: 2.4 g is 0.8 times 3 g, so CO₂ = 0.8 × 11 g = 8.8 g.']}, {'question': "Q6. In pure water (H₂O), what is the fixed mass ratio of hydrogen to oxygen according to Proust's Law?", 'options': ['2 : 1', '1 : 8', '1 : 16', '8 : 1'], 'answer': 1, 'hint': 'Compare 2 × 1 u for H against 16 u for O.', 'explanation': 'H : O mass ratio = 2 : 16 = 1 : 8.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Compare 2 × 1 u for H against 16 u for O.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: H : O mass ratio = 2 : 16 = 1 : 8.']}, {'question': 'Q7. Red cinnabar (hingula) pigment always yields mercury and sulfur in the fixed mass percentages:', 'options': ['50% Hg : 50% S', '86.22% Hg : 13.78% S', '75% Hg : 25% S', '13.78% Hg : 86.22% S'], 'answer': 1, 'hint': 'Recall Threads of Curiosity in Section 9.2.', 'explanation': 'Cinnabar (HgS) always contains 86.22% mercury and 13.78% sulfur by mass.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Recall Threads of Curiosity in Section 9.2.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: Cinnabar (HgS) always contains 86.22% mercury and 13.78% sulfur by mass.']}, {'question': 'Q8. In Example 9.3, Na and Cl combine in a 23 : 35.5 mass ratio. How much chlorine reacts with 46 g of sodium?', 'options': ['35.5 g', '71 g', '23 g', '92 g'], 'answer': 1, 'hint': '46 g is 2 × 23 g.', 'explanation': '2 × 35.5 g = 71 g of chlorine.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: 46 g is 2 × 23 g.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: 2 × 35.5 g = 71 g of chlorine.']}, {'question': 'Q9. Who is celebrated as the Father of Modern Chemistry for formulating the Law of Conservation of Mass in 1789?', 'options': ['John Dalton', 'Antoine Lavoisier', 'Joseph Louis Proust', 'Raja Ramanna'], 'answer': 1, 'hint': 'Check Meet a Scientist in Section 9.1.', 'explanation': 'Antoine Lavoisier formulated the Law of Conservation of Mass in 1789.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Check Meet a Scientist in Section 9.1.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: Antoine Lavoisier formulated the Law of Conservation of Mass in 1789.']}, {'question': "Q10. Which statement is NOT a postulate of John Dalton's 1808 Atomic Theory?", 'options': ['All matter consists of indivisible atoms', 'Atoms combine in simple whole-number ratios', 'Atoms are created and destroyed during combustion', 'Atoms of a given element are identical in mass and chemical properties'], 'answer': 2, 'hint': 'Dalton stated atoms can neither be created nor destroyed.', 'explanation': "Dalton's second postulate states atoms can neither be created nor destroyed in chemical reactions.", 'solution_steps': ['Step 1: Identify the relevant principle or formula: Dalton stated atoms can neither be created nor destroyed.', 'Step 2: Apply the given data or chemical rule carefully.', "Step 3: Dalton's second postulate states atoms can neither be created nor destroyed in chemical reactions."]}]}, {'id': 18, 'title': 'Bonding & Naming', 'subtitle': 'Quiz Challenge 2 (10 Questions): Covalent Bonds, Prefixes, Ionic Lattice & Tables 9.1', 'speech': '', 'questions': [{'question': 'Q1. Why do atoms form chemical bonds according to Section 9.4?', 'options': ['To increase potential energy', 'To achieve lower potential energy and a stable valence octet (8 e⁻) or K-shell duplet (2 e⁻)', 'To eliminate neutrons', 'To become radioactive'], 'answer': 1, 'hint': 'Bonded atoms are more stable than isolated reactive atoms.', 'explanation': 'Chemical bonding lowers potential energy by completing a stable octet or duplet.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Bonded atoms are more stable than isolated reactive atoms.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: Chemical bonding lowers potential energy by completing a stable octet or duplet.']}, {'question': 'Q2. Which molecule contains a TRIPLE covalent bond?', 'options': ['H₂', 'O₂', 'N₂', 'Cl₂'], 'answer': 2, 'hint': 'Nitrogen has 5 valence electrons and needs 3 more.', 'explanation': 'Two nitrogen atoms share 3 electron pairs (N≡N) to form a triple covalent bond.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Nitrogen has 5 valence electrons and needs 3 more.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: Two nitrogen atoms share 3 electron pairs (N≡N) to form a triple covalent bond.']}, {'question': 'Q3. What type of bonding occurs inside a single water molecule (H₂O)?', 'options': ['Ionic bond', 'Two single covalent bonds (sharing electron pairs between O and each H)', 'Double covalent bond between H and H', 'Metallic bond'], 'answer': 1, 'hint': 'Hydrogen and oxygen are both non-metals.', 'explanation': 'Oxygen shares 1 electron pair with each of two hydrogen atoms, forming two single covalent bonds.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Hydrogen and oxygen are both non-metals.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: Oxygen shares 1 electron pair with each of two hydrogen atoms, forming two single covalent bonds.']}, {'question': 'Q4. In systematic covalent naming, what are the Greek prefixes for 4, 5, and 6?', 'options': ['tri-, tetra-, penta-', 'tetra-, penta-, hexa-', 'di-, tri-, tetra-', 'mono-, di-, tri-'], 'answer': 1, 'hint': 'Check Section 9.4.1(C).', 'explanation': '4 = tetra-, 5 = penta-, 6 = hexa-.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Check Section 9.4.1(C).', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: 4 = tetra-, 5 = penta-, 6 = hexa-.']}, {'question': "Q5. Why is CO named 'carbon monoxide' instead of 'carbon monooxide'?", 'options': ['Oxygen has no prefix', "The trailing vowel 'o' of mono- is dropped before 'oxide'", 'CO is an ionic compound', 'Carbon has 2 atoms'], 'answer': 1, 'hint': 'Same vowel-dropping rule applies to pentoxide (N₂O₅).', 'explanation': 'Standard IUPAC covalent naming drops the trailing vowel in mono-/penta- before oxide.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Same vowel-dropping rule applies to pentoxide (N₂O₅).', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: Standard IUPAC covalent naming drops the trailing vowel in mono-/penta- before oxide.']}, {'question': 'Q6. Metals with fewer than 4 valence electrons typically form:', 'options': ['Negative anions by gaining electrons', 'Positive cations by losing electrons (e.g., Na → Na⁺ + e⁻)', 'Triple covalent bonds', 'Noble gases'], 'answer': 1, 'hint': 'Losing negatively charged electrons leaves a net positive charge.', 'explanation': 'Metals lose valence electrons to form positively charged cations.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Losing negatively charged electrons leaves a net positive charge.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: Metals lose valence electrons to form positively charged cations.']}, {'question': 'Q7. In the 3D crystal lattice of NaCl, each Na⁺ ion is surrounded by how many Cl⁻ ions?', 'options': ['1', '4', '6', '8'], 'answer': 2, 'hint': 'Check Threads of Curiosity in Section 9.4.2.', 'explanation': 'Each Na⁺ is surrounded by 6 Cl⁻ ions and each Cl⁻ by 6 Na⁺ ions in the 3D cubic lattice.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Check Threads of Curiosity in Section 9.4.2.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: Each Na⁺ is surrounded by 6 Cl⁻ ions and each Cl⁻ by 6 Na⁺ ions in the 3D cubic lattice.']}, {'question': 'Q8. Which polyatomic ion in Table 9.1(b) carries a POSITIVE charge?', 'options': ['Hydroxide (OH⁻)', 'Sulfate (SO₄²⁻)', 'Ammonium (NH₄⁺)', 'Nitrate (NO₃⁻)'], 'answer': 2, 'hint': 'Only one polyatomic ion in Table 9.1(b) is a cation.', 'explanation': 'Ammonium (NH₄⁺) is a +1 polyatomic cation.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Only one polyatomic ion in Table 9.1(b) is a cation.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: Ammonium (NH₄⁺) is a +1 polyatomic cation.']}, {'question': 'Q9. What is the correct formula and charge of Carbonate and Hydrogencarbonate ions in Table 9.1(b)?', 'options': ['CO₃⁻ and HCO₃²⁻', 'CO₃²⁻ and HCO₃⁻', 'CO₂²⁻ and HCO₂⁻', 'CO₄²⁻ and HCO₄⁻'], 'answer': 1, 'hint': 'Adding H⁺ reduces the 2- charge of carbonate to 1-.', 'explanation': 'Carbonate is CO₃²⁻ (valency 2) and Hydrogencarbonate is HCO₃⁻ (valency 1).', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Adding H⁺ reduces the 2- charge of carbonate to 1-.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: Carbonate is CO₃²⁻ (valency 2) and Hydrogencarbonate is HCO₃⁻ (valency 1).']}, {'question': 'Q10. Which pair of transition metal cations from Table 9.1(a) shows variable valency for Iron?', 'options': ['Fe⁺ and Fe²⁺', 'Fe²⁺ and Fe³⁺', 'Fe³⁺ and Fe⁴⁺', 'Fe⁻ and Fe²⁻'], 'answer': 1, 'hint': 'Iron forms Iron(II) and Iron(III) ions.', 'explanation': 'Iron forms Fe²⁺ (valency 2) and Fe³⁺ (valency 3).', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Iron forms Iron(II) and Iron(III) ions.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: Iron forms Fe²⁺ (valency 2) and Fe³⁺ (valency 3).']}]}, {'id': 19, 'title': 'Formulae & Properties', 'subtitle': 'Quiz Challenge 3 (10 Questions): Criss-Cross Method & Activity 9.4 Properties', 'speech': '', 'questions': [{'question': 'Q1. Using the Criss-Cross method, what is the formula of Hydrogen Sulfide (H valency 1, S valency 2)?', 'options': ['HS', 'H₂S', 'HS₂', 'H₂S₂'], 'answer': 1, 'hint': 'Cross 2 to H and 1 to S.', 'explanation': 'Crossing valencies 1 and 2 gives H₂S.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Cross 2 to H and 1 to S.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: Crossing valencies 1 and 2 gives H₂S.']}, {'question': 'Q2. What is the chemical formula of Magnesium Chloride (Mg²⁺ and Cl⁻)?', 'options': ['MgCl', 'MgCl₂', 'Mg₂Cl', 'Mg₂Cl₂'], 'answer': 1, 'hint': 'One Mg²⁺ balances two Cl⁻ ions.', 'explanation': 'Criss-crossing charges 2 and 1 gives MgCl₂.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: One Mg²⁺ balances two Cl⁻ ions.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: Criss-crossing charges 2 and 1 gives MgCl₂.']}, {'question': 'Q3. What is the simplified ionic formula of Magnesium Oxide (Mg²⁺ and O²⁻)?', 'options': ['Mg₂O₂', 'MgO', 'MgO₂', 'Mg₂O'], 'answer': 1, 'hint': 'Simplify 2:2 to lowest whole-number ratio.', 'explanation': 'Dividing Mg₂O₂ subscripts by 2 gives MgO.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Simplify 2:2 to lowest whole-number ratio.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: Dividing Mg₂O₂ subscripts by 2 gives MgO.']}, {'question': 'Q4. Which formula correctly uses brackets for a polyatomic ion?', 'options': ['MgOH₂', 'Mg(OH)₂', 'Ca(CO₃)₂', 'Al₂SO₄₃'], 'answer': 1, 'hint': 'Enclose OH⁻ in brackets when subscript > 1.', 'explanation': 'Mg²⁺ + 2 OH⁻ → Mg(OH)₂.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Enclose OH⁻ in brackets when subscript > 1.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: Mg²⁺ + 2 OH⁻ → Mg(OH)₂.']}, {'question': 'Q5. What is the formula of Calcium Carbonate (Ca²⁺ and CO₃²⁻)?', 'options': ['Ca₂(CO₃)₂', 'CaCO₃', 'Ca(CO₃)₂', 'Ca₂CO₃'], 'answer': 1, 'hint': '2+ and 2- simplify to 1:1, so no brackets are needed.', 'explanation': 'Equal 2+ and 2- charges cancel to CaCO₃.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: 2+ and 2- simplify to 1:1, so no brackets are needed.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: Equal 2+ and 2- charges cancel to CaCO₃.']}, {'question': 'Q6. In Activity 9.4, which substances dissolve readily in organic solvents like kerosene or petrol rather than water?', 'options': ['NaCl and CuSO₄', 'Camphor and Naphthalene (covalent)', 'Magnesium chloride', 'Calcium carbonate'], 'answer': 1, 'hint': 'Non-polar covalent solids dissolve in non-polar organic solvents.', 'explanation': 'Camphor and naphthalene are covalent compounds soluble in kerosene/petrol.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Non-polar covalent solids dissolve in non-polar organic solvents.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: Camphor and naphthalene are covalent compounds soluble in kerosene/petrol.']}, {'question': 'Q7. In the 9V battery conductivity test (Activity 9.4), which sample lights up the bulb?', 'options': ['Solid NaCl crystals', 'Aqueous NaCl or CuSO₄ solution', 'Aqueous sugar solution', 'Camphor in kerosene'], 'answer': 1, 'hint': 'Free mobile ions are required to carry electric current.', 'explanation': 'Aqueous NaCl/CuSO₄ contains mobile cations and anions that conduct electricity.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Free mobile ions are required to carry electric current.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: Aqueous NaCl/CuSO₄ contains mobile cations and anions that conduct electricity.']}, {'question': 'Q8. Why does aqueous sugar solution NOT conduct electricity?', 'options': ['Sugar is insoluble in water', 'Sugar is a covalent compound that dissolves as neutral molecules without forming free ions', 'Sugar absorbs all electrons', '9V is too high'], 'answer': 1, 'hint': 'No mobile ions = no electrical conduction.', 'explanation': 'Covalent sugar molecules do not dissociate into ions in water.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: No mobile ions = no electrical conduction.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: Covalent sugar molecules do not dissociate into ions in water.']}, {'question': 'Q9. Why do ionic compounds generally have much higher melting and boiling points than covalent compounds?', 'options': ['Ionic atoms are heavier', 'Strong electrostatic inter-ionic forces throughout the 3D crystal lattice require high energy to break', 'Covalent bonds are weaker than gravity', 'Ionic compounds contain neutrons'], 'answer': 1, 'hint': 'Consider the strength of attraction between + and - ions in a lattice.', 'explanation': 'Breaking strong inter-ionic electrostatic attractions requires large thermal energy.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Consider the strength of attraction between + and - ions in a lattice.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: Breaking strong inter-ionic electrostatic attractions requires large thermal energy.']}, {'question': 'Q10. Which formula represents Carbon Tetrachloride (C valency 4, Cl valency 1)?', 'options': ['CCl', 'C₄Cl', 'CCl₄', 'C₂Cl₂'], 'answer': 2, 'hint': 'Cross 4 to Cl and 1 to C.', 'explanation': 'Criss-crossing C(4) and Cl(1) gives CCl₄.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Cross 4 to Cl and 1 to C.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: Criss-crossing C(4) and Cl(1) gives CCl₄.']}]}, {'id': 20, 'title': 'Masses & Mastery', 'subtitle': 'Quiz Challenge 4 (10 Questions): Molecular Mass, Formula Unit Mass & Ion Counts', 'speech': '', 'questions': [{'question': 'Q1. What is the molecular mass of Water (H₂O) [H = 1 u, O = 16 u]?', 'options': ['17 u', '18 u', '20 u', '34 u'], 'answer': 1, 'hint': 'Compute (1 × 2) + 16.', 'explanation': 'H₂O = 2 + 16 = 18 u.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Compute (1 × 2) + 16.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: H₂O = 2 + 16 = 18 u.']}, {'question': 'Q2. What is the molecular mass of Carbon Dioxide (CO₂) [C = 12 u, O = 16 u]?', 'options': ['28 u', '44 u', '32 u', '40 u'], 'answer': 1, 'hint': 'Compute 12 + (16 × 2).', 'explanation': 'CO₂ = 12 + 32 = 44 u.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Compute 12 + (16 × 2).', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: CO₂ = 12 + 32 = 44 u.']}, {'question': 'Q3. What is the molecular mass of Nitric Acid (HNO₃) [H = 1, N = 14, O = 16 u]?', 'options': ['31 u', '47 u', '63 u', '70 u'], 'answer': 2, 'hint': 'Compute 1 + 14 + (16 × 3).', 'explanation': 'HNO₃ = 1 + 14 + 48 = 63 u.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Compute 1 + 14 + (16 × 3).', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: HNO₃ = 1 + 14 + 48 = 63 u.']}, {'question': 'Q4. What is the molecular mass of Methane (CH₄) [C = 12, H = 1 u]?', 'options': ['13 u', '16 u', '20 u', '48 u'], 'answer': 1, 'hint': 'Compute 12 + (1 × 4).', 'explanation': 'CH₄ = 12 + 4 = 16 u.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Compute 12 + (1 × 4).', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: CH₄ = 12 + 4 = 16 u.']}, {'question': 'Q5. What is the formula unit mass of Sodium Oxide (Na₂O) [Na = 23, O = 16 u]?', 'options': ['39 u', '62 u', '55 u', '78 u'], 'answer': 1, 'hint': 'Compute (23 × 2) + 16.', 'explanation': 'Na₂O = 46 + 16 = 62 u.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Compute (23 × 2) + 16.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: Na₂O = 46 + 16 = 62 u.']}, {'question': 'Q6. What is the formula unit mass of Calcium Nitrate, Ca(NO₃)₂ [Ca = 40, N = 14, O = 16 u]?', 'options': ['102 u', '164 u', '124 u', '148 u'], 'answer': 1, 'hint': 'Compute 40 + 2 × [14 + (16 × 3)].', 'explanation': '40 + 2 × 62 = 164 u.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Compute 40 + 2 × [14 + (16 × 3)].', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: 40 + 2 × 62 = 164 u.']}, {'question': 'Q7. What is the formula unit mass of Potassium Chloride (KCl) [K = 39, Cl = 35.5 u]?', 'options': ['74.0 u', '74.5 u', '75.5 u', '39.0 u'], 'answer': 1, 'hint': 'Add 39 + 35.5.', 'explanation': 'KCl = 39 + 35.5 = 74.5 u.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Add 39 + 35.5.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: KCl = 39 + 35.5 = 74.5 u.']}, {'question': 'Q8. What is the formula unit mass of Magnesium Hydroxide, Mg(OH)₂ [Mg = 24, O = 16, H = 1 u]?', 'options': ['41 u', '58 u', '42 u', '56 u'], 'answer': 1, 'hint': 'Compute 24 + 2 × (16 + 1).', 'explanation': 'Mg(OH)₂ = 24 + 34 = 58 u.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Compute 24 + 2 × (16 + 1).', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: Mg(OH)₂ = 24 + 34 = 58 u.']}, {'question': 'Q9. How many protons, neutrons, and electrons are in the Mercury ion ²⁰¹₈₀Hg²⁺?', 'options': ['80 p⁺, 121 n⁰, 80 e⁻', '80 p⁺, 121 n⁰, 78 e⁻', '78 p⁺, 121 n⁰, 80 e⁻', '80 p⁺, 201 n⁰, 78 e⁻'], 'answer': 1, 'hint': 'Neutrons = 201 - 80; 2+ charge means 2 electrons lost.', 'explanation': 'p⁺ = 80, n⁰ = 201 - 80 = 121, e⁻ = 80 - 2 = 78.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Neutrons = 201 - 80; 2+ charge means 2 electrons lost.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: p⁺ = 80, n⁰ = 201 - 80 = 121, e⁻ = 80 - 2 = 78.']}, {'question': 'Q10. To balance a total positive charge of +6 from two Al³⁺ ions, how many SO₄²⁻ ions are needed?', 'options': ['1', '2', '3', '6'], 'answer': 2, 'hint': 'Each SO₄²⁻ brings -2 charge; reach -6.', 'explanation': '3 × (-2) = -6, balancing 2 × (+3) = +6 in Al₂(SO₄)₃.', 'solution_steps': ['Step 1: Identify the relevant principle or formula: Each SO₄²⁻ brings -2 charge; reach -6.', 'Step 2: Apply the given data or chemical rule carefully.', 'Step 3: 3 × (-2) = -6, balancing 2 × (+3) = +6 in Al₂(SO₄)₃.']}]}]
